INSERT INTO courses (id, owner, language, title, description, published)
VALUES ('39758f07-7943-596e-af46-b699bb5d26a1', 'kodr-catalog', 'JAVA', 'Основы Java', 'Курс по синтаксису Java, классам, ООП и исключениям. Краткие конспекты и задания. В каждом уроке есть ссылка на соответствующую страницу учебника Metanit.', TRUE);

INSERT INTO course_modules (id, course_id, title, position) VALUES
    ('f9127206-b819-5dec-9221-bf0852a4a5f9', '39758f07-7943-596e-af46-b699bb5d26a1', 'Введение в Java', 0),
    ('50dcf1ee-e95b-5071-b34c-37b5fc78308a', '39758f07-7943-596e-af46-b699bb5d26a1', 'Основы программирования', 1),
    ('0db87cc0-1672-5f33-af5b-0cf761862b11', '39758f07-7943-596e-af46-b699bb5d26a1', 'Классы и методы', 2),
    ('8bf47c2d-4bc7-5e6e-878b-df316d82406c', '39758f07-7943-596e-af46-b699bb5d26a1', 'Объектно-ориентированное программирование', 3),
    ('43f6c309-8879-5934-9400-38e92699168e', '39758f07-7943-596e-af46-b699bb5d26a1', 'Обработка исключений', 4);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('98539d58-908d-58c4-9553-9ab01ad62b6a', 'f9127206-b819-5dec-9221-bf0852a4a5f9', 'Как запускается Java',
     $lesson$Компилятор javac переводит исходный текст в байткод. Байт-код загружает JVM, которая работает на конкретной операционной системе. За счёт этого тот же .class можно запустить на разных платформах при наличии совместимой JVM. Библиотеки, требующие нативных компонентов, могут накладывать дополнительные ограничения.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/1.1.php)$lesson$, 0),
    ('973792b2-d7b0-5e84-8b10-f4f3e85643ed', 'f9127206-b819-5dec-9221-bf0852a4a5f9', 'Установка и проверка JDK',
     $lesson$Поставьте JDK для своей ОС и архитектуры. Проверьте команды java -version и javac -version. Если версии различаются, проверьте порядок каталогов в PATH. Переменная JAVA_HOME обычно указывает на корень JDK, а в PATH добавляют его каталог bin.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/1.6.php)$lesson$, 1),
    ('40f9c8fd-d547-5689-b491-6907712a1029', 'f9127206-b819-5dec-9221-bf0852a4a5f9', 'Первая программа из терминала',
     $lesson$Создайте Main.java с классом Main и точкой входа public static void main(String[] args). Добавьте в неё System.out.println("Привет, Java!"). Команда javac Main.java создаст Main.class, а java Main запустит класс. При запуске уже скомпилированного класса расширение .class указывать не нужно.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/1.2.php)$lesson$, 2),
    ('1ce85987-86d7-50b2-a361-9c410f0dd235', 'f9127206-b819-5dec-9221-bf0852a4a5f9', 'Запуск программы в IntelliJ IDEA',
     $lesson$В новом Java-проекте выберите установленный JDK, создайте класс Main и добавьте метод main. Запустите метод через кнопку рядом с его объявлением и проверьте консоль Run. Если IDE использует другую версию JDK, проверьте Project SDK и настройки запуска.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/1.5.php)$lesson$, 3),
    ('8545b717-1d8a-59bb-ad72-8382dd469ef4', 'f9127206-b819-5dec-9221-bf0852a4a5f9', 'Запуск программы в NetBeans',
     $lesson$Создайте Java-проект и выберите класс с методом main как точку запуска. Run Project компилирует исходники и показывает вывод в окне Output. Если IDE просит указать главный класс или не видит методы новых версий Java, проверьте настройки проекта и выбранную Java Platform.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/1.3.php)$lesson$, 4),
    ('1917fca7-f53b-5894-b3c0-1cf55ea5d346', 'f9127206-b819-5dec-9221-bf0852a4a5f9', 'Запуск программы в Eclipse',
     $lesson$Создайте Java Project и добавьте класс с методом main в папку исходников. Запустите класс командой Run As → Java Application. Если появляется ошибка версии классов, проверьте Installed JREs, Java Build Path и уровень компиляции проекта.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/1.4.php)$lesson$, 5),
    ('8bad6279-67db-5e88-ade8-80cbad0d4c14', 'f9127206-b819-5dec-9221-bf0852a4a5f9', 'Быстрые эксперименты в JShell',
     $lesson$JShell вычисляет выражения и принимает небольшие объявления по одному. Попробуйте ввести 12 * 7, затем объявите переменную и используйте её в следующем выражении. Команда /vars покажет переменные, /exit завершит сеанс. Такой эксперимент можно провести без класса Main.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/1.7.php)$lesson$, 6);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('99b7714a-14a7-5f06-ac5e-f8082bf4d91d', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Из чего состоит программа',
     $lesson$В классическом файле Java размещают объявления пакета, импорты и классы. Внутри класса определяют поля и методы, а исполняемые инструкции помещают в блок метода или инициализатора. Файл с открытым классом Route называется Route.java. Отступы помогают увидеть вложенность, которую для компилятора задают фигурные скобки.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.11.php)$lesson$, 0),
    ('b52a4c03-6f1e-5e74-924d-ee262b8aec79', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Переменные и константы',
     $lesson$При объявлении переменной выбирают тип и имя. Например, int seats = 12 задаёт изменяемое целое значение. У final-переменной присваивание разрешено только один раз. Если final применён к ссылке, это запрещает заменить саму ссылку, а возможность изменить объект определяется его классом.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.1.php)$lesson$, 1),
    ('d1c24b8f-0557-5242-9a54-b5ea683a73d5', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Литералы в коде',
     $lesson$Литерал задаёт значение прямо в тексте программы. Например, 0b1010 — двоичное целое, 500L — long, 1.5F — float, 'A' — char, "A" — строка. Последовательность \n в строковом литерале обозначает перевод строки. null обозначает отсутствие ссылки и не присваивается примитивам.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.19.php)$lesson$, 2),
    ('37fcbc69-c5e9-5247-b30f-e7abbf351343', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Примитивы и ссылки',
     $lesson$Целые примитивы отличаются диапазонами, boolean хранит true или false, а char представляет кодовую единицу UTF-16. Переменные ссылочного типа содержат ссылки на объекты. Для десятичных чисел float и double сохраняют приближённое значение, поэтому равенство результатов вычислений требует аккуратности.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.12.php)$lesson$, 3),
    ('79eef972-427c-5995-9c7c-e9e3c023231d', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Ввод и вывод в консоли',
     $lesson$System.out.println печатает значение и завершает строку. Scanner может прочитать очередное число методом nextInt() или целую строку методом nextLine(). После чтения числа перевод строки остаётся во входе. Для задач с автоматической проверкой выводите только то, что требует условие.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.9.php)$lesson$, 4),
    ('54ba0454-96f5-5331-a8b0-87c5b5bb60ab', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Арифметика и целочисленное деление',
     $lesson$Операторы +, -, *, / и % выполняют базовые операции. Если обе стороны деления целые, дробная часть результата отбрасывается в сторону нуля. Так, -7 / 3 равно -2, а -7 % 3 равно -1. Для дробного результата преобразуйте хотя бы один операнд в double до деления.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.3.php)$lesson$, 5),
    ('b58bf7fe-1dac-5f9d-ba5f-ef65ab6c2bd4', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Операции над битами',
     $lesson$Битовые операторы &, | и ^ работают с разрядами целых чисел. Сдвиг << перемещает биты влево, >> сохраняет знак при правом сдвиге, а >>> заполняет освободившиеся разряды нулями. Для проверки бита с номером k можно сравнить flags & (1 << k) с нулём.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.13.php)$lesson$, 6),
    ('67236600-10cb-5c22-a007-e341ae165c73', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Сравнение и составные условия',
     $lesson$Сравнения возвращают boolean. Условия && и || вычисляют правую часть только когда она влияет на результат. Например, проверка item != null && item.isReady() безопасна при отсутствии объекта. Для сравнения содержимого строк используйте equals, а == сравнивает ссылки.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.14.php)$lesson$, 7),
    ('95b32e1e-63cd-5751-8dc0-8ca9b41915db', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Присваивание и порядок операций',
     $lesson$Оператор += обновляет переменную с использованием её прежнего значения. Приоритет определяет группировку выражения: 2 + 3 * 4 равно 14, а (2 + 3) * 4 равно 20. Явные скобки помогают читать сложные условия и избегать неверной интерпретации.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.15.php)$lesson$, 8),
    ('34337b87-3db2-5201-835e-fe686b0a3f8c', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Преобразования числовых типов',
     $lesson$Присваивание int переменной типа long выполняется неявно. Сужающее преобразование требует указания целевого типа и может потерять информацию. Например, (int) 8.9 даёт 8, а сохранение большого int в byte оставит младшие биты. Проверяйте допустимый диапазон до преобразования.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.2.php)$lesson$, 9),
    ('4729fd03-6bf9-5fca-8940-ee9b43a59585', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Ветвление через if и else',
     $lesson$Условие if выполняет блок при истинном выражении. В цепочке if, else if и else срабатывает первая подходящая ветвь. При классификации температуры сначала можно проверить отрицательные значения, затем ноль, а положительный случай оставить для else. Обязательно проверяйте границы диапазонов.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.5.php)$lesson$, 10),
    ('7929b8ee-8ed7-5721-8540-ac036d76a17c', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Циклы и управление повторениями',
     $lesson$Цикл while проверяет условие перед телом, а do-while выполнит тело хотя бы раз. Цикл for удобно использовать, когда ясно, как меняется счётчик. break завершает ближайший цикл, continue переходит к следующей итерации. Для индексов массива обычно нужна граница i < length.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.6.php)$lesson$, 11),
    ('598bed5d-6e4e-504d-a6ae-7fd522d78b6e', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Массивы и индексы',
     $lesson$Массив хранит фиксированное число элементов одного типа. Индекс начинается с нуля, поэтому последний допустимый индекс равен length - 1. Для обхода без изменения массива подходит for-each. Перед чтением первого элемента убедитесь, что массив не пуст.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.4.php)$lesson$, 12),
    ('6fdc82aa-fcb3-5b1d-b04b-4119ee32fc80', '50dcf1ee-e95b-5071-b34c-37b5fc78308a', 'Варианты switch',
     $lesson$Оператор switch выбирает ветвь по значению. В классической записи с case и двоеточием выполнение может перейти к следующей ветви без break. Ветви со стрелками работают без такого перехода. В Java 14 и новее switch может возвращать значение, а блок ветви возвращает результат через yield.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.20.php)$lesson$, 13);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('3a532fab-c3b4-503e-ad74-4782e01de13b', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Класс, объект и ссылка',
     $lesson$Класс описывает состояние и поведение, а объект представляет конкретный экземпляр. Два экземпляра класса Counter могут иметь разные значения поля count. Если две переменные ссылаются на один экземпляр, изменение через одну переменную будет заметно через другую.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.1.php)$lesson$, 0),
    ('96ecc9fc-3446-5184-bb5f-49ce1886f9bc', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Объявление и вызов методов',
     $lesson$Метод объединяет инструкции под именем. В его объявлении указывают тип результата и параметры, например static int square(int value). Код вызова передаёт аргумент, а метод вычисляет результат. void используют для действий, которые ничего не возвращают.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.7.php)$lesson$, 1),
    ('3b1b6e66-1ebb-5cdc-857c-02f12181f266', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Параметры и аргументы',
     $lesson$Параметры описывают данные, ожидаемые методом, а аргументы — конкретные значения при вызове. В методе log(String prefix, int... values) последний параметр принимает переменное число int. Внутри метода он доступен как массив, в том числе пустой.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.16.php)$lesson$, 2),
    ('5b2460b6-c925-58a4-82f0-7e2e54919d6e', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Передача объектов в методы',
     $lesson$Java передаёт аргументы по значению. Для объекта копируемым значением является ссылка. Метод может изменить поля объекта по полученной ссылке, но присваивание параметру новой ссылки не заменит переменную вызывающего кода.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.14.php)$lesson$, 3),
    ('ffd4b076-be0a-50ea-9c98-efdbc937ad60', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Возврат результата из метода',
     $lesson$return завершает выполнение метода. Если метод возвращает значение, оно должно быть совместимо с объявленным типом и доступно на каждом пути, который завершается нормально. В void-методе return без выражения позволяет выйти раньше, например при пустом входе.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.17.php)$lesson$, 4),
    ('4b347371-b1bb-5642-a9c3-623f22d6cac5', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Перегрузка методов',
     $lesson$Класс может объявить несколько методов с одинаковым именем и разными списками типов параметров. Компилятор выбирает перегрузку по аргументам. Одного отличия в типе результата недостаточно. Вызовы с null могут оказаться неоднозначными, если возможны несвязанные ссылочные типы.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.18.php)$lesson$, 5),
    ('4e004c4c-60d1-5e65-be5c-6dad5c5e02d9', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Конструкторы и инициализация',
     $lesson$Конструктор задаёт начальное состояние экземпляра и носит имя класса. Через this(...) можно вызвать другой конструктор этого класса, а через super(...) — конструктор родителя. Инициализаторы экземпляра выполняются при создании объекта. Если класс уже объявил свой конструктор, компилятор не добавит конструктор без аргументов автоматически.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.21.php)$lesson$, 6),
    ('3e1d8b93-3d7d-51ec-b386-722d33053e76', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Статические методы и поля',
     $lesson$static-член относится к классу. Например, счётчик созданных экземпляров можно хранить в общем статическом поле. Обычное поле принадлежит каждому объекту. У static-метода отсутствует ссылка this, поэтому для обращения к полю экземпляра нужна явная ссылка.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.4.php)$lesson$, 7),
    ('4d283f20-9883-5bb3-82bc-0c0da62ce32d', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Область видимости переменной',
     $lesson$Локальная переменная доступна в пределах блока, где объявлена. Переменная цикла for обычно недоступна после цикла. Поля доступны через объект или класс с учётом модификаторов доступа. Если параметр совпадает по имени с полем, запись this.name явно обозначает поле.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.20.php)$lesson$, 8),
    ('9f26dee2-0828-5239-8f89-74c1e6d4584d', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Рекурсивный вызов',
     $lesson$При рекурсии метод вызывает себя на более простой версии задачи. Нужен базовый случай, прекращающий вызовы. В рекурсивной сумме от 1 до n переходят к n - 1 и завершают вычисление при n = 0. При большой глубине вызовов разумнее выбрать цикл.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.8.php)$lesson$, 9),
    ('debbbd00-77fe-5ef6-8916-731535d0e4aa', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Организация исходников в пакеты',
     $lesson$Пакеты задают пространство имён. Объявление package обычно соответствует структуре папок исходников. import позволяет использовать короткое имя чужого класса, иначе доступно полное квалифицированное имя. Два одинаковых коротких имени можно различить полными путями.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.2.php)$lesson$, 10),
    ('88aa9462-e6d7-5c31-a99e-ac14aff0e5f6', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Видимость классов и членов',
     $lesson$private ограничивает доступ классом, а отсутствие модификатора обычно означает доступ в пределах пакета. protected дополнительно открывает доступ наследникам с правилами Java, public предоставляет самый широкий доступ. Для деталей реализации удобнее выбирать минимальный нужный уровень видимости.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.3.php)$lesson$, 11),
    ('f570d004-1596-5cab-98bd-3db4937887e5', '0db87cc0-1672-5f33-af5b-0cf761862b11', 'Компактная точка входа',
     $lesson$В Java 25 компактный исходный файл может содержать метод void main() без явного объявления класса. Это удобно для небольших учебных программ. Для практики в Kodr используйте класс Main с традиционным public static void main(String[] args), чтобы исходник работал на Java 13 в стандартном Judge0.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.19.php)$lesson$, 12);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('3871d6fd-1554-556b-ad5f-88bd6d9cacbe', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Инкапсуляция и инварианты',
     $lesson$Инкапсуляция помогает сохранять корректное состояние объекта. Закройте изменяемые поля и предоставьте операции, которые проверяют входные данные. У класса банковского счёта метод снятия может проверять доступный баланс вместо открытого изменения поля.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.22.php)$lesson$, 0),
    ('4fa17b9c-bee6-57b0-bf23-d2c9924198c8', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Наследование классов',
     $lesson$Класс с extends расширяет один родительский класс. Общие операции можно объявить в родителе, а особенности — в наследнике. Чтобы вызвать конструктор родителя, используют super(...). Наследование удобно там, где экземпляр наследника действительно можно использовать как экземпляр родителя.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.5.php)$lesson$, 1),
    ('4abd9a84-5432-5c32-9a4a-05b92924cab4', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Ограничения наследования и переопределения',
     $lesson$Класс final нельзя расширить, а метод final нельзя переопределить в наследнике. Отдельно private-член скрыт от наследника и не участвует в обычном переопределении. Помечайте метод final, если подклассы не должны менять гарантии его поведения.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.23.php)$lesson$, 2),
    ('5d344174-3f5c-5294-9d01-604d9720a218', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Полиморфизм методов',
     $lesson$При вызове переопределённого метода экземпляра реализацию выбирают по реальному классу объекта. Например, Shape shape = new Circle() вызывает реализацию Circle для shape.area(). Аннотация @Override позволяет компилятору проверить, что метод действительно переопределяет существующий.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.24.php)$lesson$, 3),
    ('0afbbc30-7d3a-5c21-b979-17c337e86dba', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Общие методы Object',
     $lesson$Обычный класс без явного родителя наследует Object. Переопределённый toString помогает вывести понятное представление экземпляра. Если equals считает два объекта равными, их hashCode должен совпадать. Иначе хеш-коллекции могут неправильно находить ключи.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.9.php)$lesson$, 4),
    ('6098b18f-3e09-51ad-b16a-b0badfcc2fc6', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Абстрактные классы',
     $lesson$Абстрактный класс может хранить общие поля и реализованные методы, но его нельзя создать напрямую. Абстрактный метод задаёт сигнатуру без реализации. Конкретный наследник должен предоставить недостающие реализации. Такой шаблон подходит для семейства объектов с общим состоянием.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.6.php)$lesson$, 5),
    ('ddd7d90b-f410-5795-b406-ca00e50fa7c5', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Преобразования в иерархии типов',
     $lesson$Ссылку на наследника можно присвоить переменной родительского типа без явного преобразования. Обратное приведение допустимо, только если объект действительно имеет совместимый тип. Перед приведением проверяйте instanceof. Иначе возможен ClassCastException.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.10.php)$lesson$, 6),
    ('53cc71ce-b8ae-5825-a438-4867956f5259', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Контракты интерфейсов',
     $lesson$Интерфейс объявляет договор между вызывающим кодом и реализацией. Класс объявляет реализацию через implements. Интерфейс может содержать абстрактные, default и статические методы. В отличие от класса, он не хранит состояние конкретного экземпляра в обычных полях.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.7.php)$lesson$, 7),
    ('ab196f74-234d-5563-8f25-a7823be6319e', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Замена реализации через интерфейс',
     $lesson$Метод может принимать интерфейс, например Printable, и вызывать print без знания класса аргумента. Настольный принтер и виртуальный экспорт тогда подходят под один контракт. В тестах можно подставить небольшую реализацию, сохраняющую печать в памяти.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.28.php)$lesson$, 8),
    ('84bbe319-0702-542d-9993-5f77ca78f64d', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Комбинирование интерфейсов',
     $lesson$Класс может реализовать несколько интерфейсов, а интерфейс может расширять несколько интерфейсов. Если два несвязанных интерфейса задают одинаковую default-реализацию по сигнатуре, класс должен явно разрешить конфликт. При необходимости он может вызвать метод определённого интерфейса через InterfaceName.super.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.29.php)$lesson$, 9),
    ('2cbd2860-3fce-5e30-9242-74a9e7367257', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Интерфейс как обратный вызов',
     $lesson$Обратный вызов — операция, которую передают другому компоненту для исполнения позднее. Например, загрузчик может вызвать onComplete после окончания работы. Компоненту достаточно интерфейса обработчика, поэтому его можно использовать с разными реакциями на событие.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.16.php)$lesson$, 10),
    ('2ad51066-5926-5bf5-8486-424ad2bebeb6', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Фиксированный набор значений enum',
     $lesson$enum удобно использовать для известных состояний, например WAITING, RUNNING и DONE. Элемент перечисления может иметь дополнительные данные и методы. Для записи в файл или базу выбирайте стабильное имя или отдельный код. Позиция ordinal может измениться при перестановке элементов.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.8.php)$lesson$, 11),
    ('d961f98e-2191-543c-b81d-3f77311d0d44', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Параметры типов',
     $lesson$Параметризованный класс Box<T> позволяет указать тип содержимого при создании. Так компилятор обнаруживает несовместимое значение без приведения при чтении. Примитивы нельзя указывать аргументами типов, поэтому для int используют Integer.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.11.php)$lesson$, 12),
    ('531afa9a-be31-5508-9dd3-a2b8f0742555', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Границы параметров типов',
     $lesson$Ограничение T extends Number позволяет работать с Number-методами внутри обобщённого кода. Оно также не позволяет передать несовместимый тип. Верхнюю границу можно сочетать с интерфейсами, например T extends Number & Comparable<T>.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.17.php)$lesson$, 13),
    ('aba841aa-aab1-53e0-ad27-4c00396307de', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Наследование обобщённых типов',
     $lesson$Подкласс может передавать конкретный тип родителю или оставаться параметризованным. Но наследование String от Object не делает List<String> подтипом List<Object>. Иначе через ссылку List<Object> можно было бы добавить произвольный объект в список строк.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.15.php)$lesson$, 14),
    ('d0b18fed-571f-5a48-8e10-25e580b68a83', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Что происходит при стирании типов',
     $lesson$Компилятор проверяет обобщения, а при генерации байткода заменяет параметры типов их границами или Object. Поэтому нельзя создать new T() или проверить instanceof List<String> обычным способом. Если тип нужен во время выполнения, его передают отдельно, например через Class<T>.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.31.php)$lesson$, 15),
    ('129401f7-eb1e-5cf3-a47e-66e73027406f', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Подстановки с ? extends и ? super',
     $lesson$List<? extends Number> позволяет читать элементы как Number, но добавлять произвольные числа туда нельзя. List<? super Integer> допускает добавление Integer, однако прочитанное значение имеет гарантированный тип Object. Правило удобно запоминать по роли коллекции: источник — extends, приёмник — super.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.32.php)$lesson$, 16),
    ('440f7065-5063-5036-8370-68832bb75bb6', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Копии ссылок и объектов',
     $lesson$Присваивание ссылочной переменной копирует ссылку, оставляя один объект. Поверхностная копия создаёт новый внешний объект, но вложенные изменяемые объекты могут остаться общими. Для независимой копии явно создайте нужные вложенные значения, например через конструктор копирования.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.13.php)$lesson$, 17),
    ('6d0f3043-16af-5735-ac62-5ce242a1fa98', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Хранение данных в record',
     $lesson$Начиная с Java 16 record задаёт компактный тип для группы значений. Компилятор создаёт методы доступа, equals, hashCode и toString. Компоненты нельзя переприсвоить, но изменяемое значение внутри компонента остаётся изменяемым. Проверки входных данных можно разместить в компактном конструкторе.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.18.php)$lesson$, 18),
    ('0564910e-f068-5762-a88a-d7fa2ab6d4f1', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Функциональные интерфейсы и ссылки на методы',
     $lesson$Функциональный интерфейс имеет один абстрактный метод. @FunctionalInterface проверяет это ограничение при компиляции. Ссылка String::length подходит там, где ожидается операция от строки к целому, если сигнатуры совместимы.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/9.4.php)$lesson$, 19),
    ('c3aa4d2b-3609-580b-9617-870546e486db', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Лямбда как реализация операции',
     $lesson$Лямбда выражает поведение функционального интерфейса. Например, x -> x * 2 удваивает аргумент при подходящем целевом типе. Для нескольких инструкций понадобятся фигурные скобки и явный return, если функциональный метод должен возвращать значение.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/9.1.php)$lesson$, 20),
    ('a704f61c-4b0a-5ff8-9fe1-131e70336ca0', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Передача и возврат функций',
     $lesson$Метод может получать или возвращать значение функционального интерфейса. Метод, возвращающий x -> x + offset, может настроить операцию прибавления. Локальная переменная offset, захватываемая лямбдой, должна быть final или фактически неизменной.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/9.2.php)$lesson$, 21),
    ('91b3fc6f-1d9a-5a07-965c-e31d659a891c', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Стандартные функциональные интерфейсы',
     $lesson$Predicate<T> проверяет условие, Function<T, R> преобразует значение, Consumer<T> принимает значение без результата, Supplier<T> возвращает значение без аргументов. Для числовых вычислений доступны специализации, например IntUnaryOperator. Они помогают обрабатывать примитивы без упаковки.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/9.3.php)$lesson$, 22),
    ('caa7b5f8-9c3b-50ac-99c7-589417faa3f6', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Внутренние и статические вложенные классы',
     $lesson$Обычный внутренний класс связан с экземпляром внешнего класса и может обращаться к его состоянию. Статический вложенный класс такой связи не имеет. Используйте вложенность, если отдельный вспомогательный тип нужен одному внешнему классу и понятен рядом с ним.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.12.php)$lesson$, 23),
    ('1e6a5ffe-0873-5bfa-b02a-e4c88d68840e', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Анонимные классы',
     $lesson$Выражение new InterfaceName() { ... } создаёт экземпляр класса без явного имени. Оно подходит для разовой реализации и может содержать собственные поля и несколько методов. Если нужно реализовать только один функциональный метод, лямбда обычно короче.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.30.php)$lesson$, 24),
    ('d55d1c6a-6fed-5a5a-bd20-09707fea7c54', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Закрытые иерархии sealed',
     $lesson$В Java 17 sealed-класс или интерфейс ограничивает список непосредственных наследников. Этот список можно указать через permits. Разрешённый наследник продолжает иерархию как sealed, закрывает её как final или открывает как non-sealed. Это удобно, когда допустимые варианты предметной модели известны заранее.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.25.php)$lesson$, 25),
    ('963a06e0-755a-5854-86d7-ea9edee57d50', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Сопоставление с типом',
     $lesson$В Java 16 и новее условие obj instanceof String text одновременно проверяет тип и объявляет переменную text. Её можно использовать там, где проверка гарантированно успешна. Это уменьшает количество явных приведений в ветвлениях. В современном switch также поддерживаются шаблоны типов.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.26.php)$lesson$, 26),
    ('20be45c2-151e-5c36-8d8d-458e83a0ae99', '8bf47c2d-4bc7-5e6e-878b-df316d82406c', 'Извлечение компонентов record шаблоном',
     $lesson$В Java 21 record-паттерн позволяет проверить тип и получить компоненты, например value instanceof Point(int x, int y). Шаблоны могут быть вложенными. Такой подход удобен в switch, где над разными вариантами записи выполняются разные вычисления.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/3.27.php)$lesson$, 27);

INSERT INTO lessons (id, module_id, title, content, position) VALUES
    ('5808dc97-d272-5d7b-9d33-9e9bc1d34a39', '43f6c309-8879-5934-9400-38e92699168e', 'Блоки try, catch и finally',
     $lesson$Поместите потенциально ошибочную операцию в try, а обработку ожидаемого исключения — в catch с подходящим типом. Более узкие типы ставят раньше общих. finally обычно выполняется при выходе из блока, включая исключение или return. Для закрытия ресурсов предпочтительна конструкция try-with-resources.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/2.10.php)$lesson$, 0),
    ('bde5bf3b-a715-5a32-9b9f-68245e7747d7', '43f6c309-8879-5934-9400-38e92699168e', 'Иерархия исключений',
     $lesson$Throwable лежит в основе Exception и Error. RuntimeException и Error не требуют объявления в throws или перехвата. Для проверяемых исключений компилятор требует определить обработчик либо объявить распространение. При перехвате сохраняйте причину, если передаёте ошибку дальше.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/4.2.php)$lesson$, 1),
    ('bf7e300b-fd3a-5895-91f6-859a154e3884', '43f6c309-8879-5934-9400-38e92699168e', 'Разница между throw и throws',
     $lesson$throw прекращает обычный поток выполнения и передаёт конкретный объект исключения. throws в сигнатуре перечисляет исключения, которые могут выйти из метода. Например, проверка отрицательного количества может выполнить throw new IllegalArgumentException("Количество отрицательно").

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/4.1.php)$lesson$, 2),
    ('a2c4cf61-64c8-57c9-b4ff-312122301d87', '43f6c309-8879-5934-9400-38e92699168e', 'Собственный класс исключения',
     $lesson$Собственный тип пригодится, когда вызывающий код должен различать сбои предметной области. Выберите Exception для проверяемого исключения или RuntimeException для непроверяемого. Передайте сообщение и исходную причину конструктору родителя. Понятное имя помогает выбрать обработчик.

[Metanit — оригинальный урок](https://metanit.com/java/tutorial/4.3.php)$lesson$, 3),
    ('28cac2a2-f24b-5520-ac56-b42aeb47f4cd', '43f6c309-8879-5934-9400-38e92699168e', 'Проверки assert',
     $lesson$assert проверяет предположение разработчика о внутреннем состоянии. При нарушении включённой проверки Java создаёт AssertionError. Подключить такие проверки при запуске можно флагом java -ea. Проверка входных данных и обязательные действия должны работать при любой настройке assert, поэтому их выносят в обычный код.

